html:
{% set lot_no = doc.production_lot_no or doc.name %}
{% set wo_url = frappe.utils.get_url() + "/app/work-order/" + doc.name %}

<style>
  .lot-label {
    width: 88mm;
    min-height: 60mm;
    padding: 6mm 8mm;
    font-family: 'Noto Sans KR', sans-serif;
    box-sizing: border-box;
    border: 1px solid #ddd;
  }
  .company-name {
    font-size: 9pt;
    color: #666;
    margin-bottom: 3mm;
  }
  .lot-row {
    display: flex;
    align-items: center;
    gap: 6mm;
    margin-bottom: 4mm;
  }
  .qr-img { width: 28mm; height: 28mm; flex-shrink: 0; }
  .lot-no {
    font-size: 16pt;
    font-weight: bold;
    letter-spacing: 1px;
    line-height: 1.2;
    word-break: break-all;
  }
  table.fields { width: 100%; border-collapse: collapse; font-size: 9pt; }
  table.fields td { padding: 1mm 0; }
  table.fields td:first-child { color: #888; width: 22mm; }
  table.fields td:last-child { font-weight: 500; }
  .divider { border-top: 1px solid #eee; margin: 3mm 0; }
</style>

<div class="lot-label">

  <div class="company-name">{{ doc.company }}</div>

  <div class="lot-row">
    <img class="qr-img"
         src="data:image/png;base64,{{ get_qr_png(wo_url, 5) }}"
         alt="QR" />
    <div class="lot-no">{{ lot_no }}</div>
  </div>

  <div class="divider"></div>

  <table class="fields">
    <tr>
      <td>품목</td>
      <td>{{ doc.production_item_name or doc.production_item }}</td>
    </tr>
    <tr>
      <td>생산수량</td>
      <td>{{ doc.qty | int }} {{ doc.stock_uom }}</td>
    </tr>
    {% if doc.mfg_date %}
    <tr>
      <td>제조일자</td>
      <td>{{ doc.mfg_date }}</td>
    </tr>
    {% endif %}
    {% if doc.best_before_date %}
    <tr>
      <td>유통기한</td>
      <td>{{ doc.best_before_date }}</td>
    </tr>
    {% endif %}
    {% if doc.production_line %}
    <tr>
      <td>생산라인</td>
      <td>{{ doc.production_line }}</td>
    </tr>
    {% endif %}
  </table>

</div>
